{
  "positionId": "P01",
  "interviews": [
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I1",
      "interviewBlueprint": {
        "questionIntent": "느린 조회 쿼리에 맞는 개선 방법을 선택할 수 있는지 확인한다. 실행 계획에서 확인한 병목과 인덱스 추가·조인 정리를 선택한 근거의 연결에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓 운영 화면의 신고 목록 조회 쿼리가 3.2초 걸렸다.",
          "task": "신고 목록 조회에 조회 조건에 맞는 인덱스를 추가하고 조인 순서를 정리했다.",
          "action": "실행 계획에서 확인한 신고 테이블과 판매글 테이블의 전체 조인을 근거로, 인덱스 추가와 조인 정리가 해당 병목에 적절하다고 판단한 이유를 설명한다.",
          "result": "조회 시간이 0.4초로 줄어든 결과를 선택한 방법의 근거와 연결해 설명한다."
        },
        "expectedEvidence": [
          "인덱스 추가와 조인 정리를 선택한 구체적인 근거",
          "그 근거를 뒷받침하는 실행 계획의 내용과 조회 조건"
        ]
      },
      "question": "포켓마켓에서 신고 목록 조회를 3.2초에서 0.4초로 줄이셨을 때, 인덱스 추가와 조인 정리를 택한 근거는 무엇이었나요?",
      "answerTip": "가장 전하고 싶은 내용부터 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "실행 계획에서 확인한 병목을 인덱스 추가와 조인 정리의 선택 근거로 구체적으로 제시한다.",
            "조회 조건과 테이블 접근 방식에 비춰 선택한 변경이 불필요한 조회나 조인 부담을 줄이는 이유를 타당하게 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "인덱스 추가와 조인 정리를 선택한 이유를 설명하지만 실행 계획이나 조회 조건과의 연결은 일부만 제시한다.",
            "변경이 조회 속도를 높인다는 설명은 타당하지만 해당 쿼리의 병목에 적합한 이유는 일반적인 수준에 머문다."
          ]
        },
        "poor": {
          "criteria": [
            "적용한 변경이나 단축된 시간만 말하고 해당 방법을 선택한 근거는 제시하지 못한다.",
            "선택 근거가 조회 쿼리의 병목과 무관하거나 인덱스와 조인의 동작을 잘못 이해한 설명에 의존한다."
          ]
        }
      }
    },
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I2",
      "interviewBlueprint": {
        "questionIntent": "운영 오류의 원인에 맞는 수정 조치를 구체적으로 설명할 수 있는지 확인한다. 두 서버에서 발생한 스케줄러 중복 실행을 막는 잠금 처리에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓에서 배포 다음 날 같은 알림이 두 번 발송된다는 문의가 들어왔고, 시간순으로 확인한 로그에서 스케줄러가 서버 두 대에서 동시에 실행되고 있었다.",
          "task": "잠금 키를 두는 방식으로 스케줄러 중복 실행 오류를 수정했다.",
          "action": "실제로 적용한 잠금 키 처리 방식을 설명하고, 두 서버의 동시 실행을 어떤 동작으로 제한했는지 밝힌다.",
          "result": "설명한 잠금 처리로 같은 스케줄러 작업의 중복 실행이 차단되는 원리를 설명한다."
        },
        "expectedEvidence": [
          "스케줄러에 실제로 적용한 잠금 처리 방식",
          "두 서버가 동시에 실행을 시도할 때 중복 실행을 제한하는 잠금의 동작"
        ]
      },
      "question": "포켓마켓에서 배포 후 알림 중복 발송 오류를 잠금 키로 고치셨을 때, 스케줄러에 적용한 잠금 처리 방식은 무엇이었나요?",
      "answerTip": "직접 하신 일을 중심으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "잠금 키를 확인하거나 획득하는 방식과 잠금 상태에 따른 스케줄러 실행 동작을 구체적으로 설명한다.",
            "설명한 잠금 처리가 두 서버의 동시 실행을 제한할 수 있으며, 확인된 중복 실행 원인에 맞는 수정 조치다."
          ]
        },
        "acceptable": {
          "criteria": [
            "잠금 상태에 따라 스케줄러 실행을 제한한 방식을 설명하지만 실제 처리 내용은 일부 불분명하다.",
            "두 서버의 중복 실행을 막겠다는 방향은 타당하지만 동시 실행 시 잠금이 작동하는 설명이 충분하지 않다."
          ]
        },
        "poor": {
          "criteria": [
            "잠금을 사용했다는 말만 반복하거나 로그를 확인한 내용만 말하고 실제 잠금 처리 방식은 설명하지 못한다.",
            "설명한 잠금 처리가 서버 간 동시 실행을 제한하지 못하거나 알림 중복 발송의 확인된 원인과 무관하다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P02",
  "interviews": [
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "흩어진 요청을 개발·디자인 담당자가 구현 범위를 이해할 수 있는 요구사항 문서로 구체화하는 능력을 검증한다. 판단 초점은 실제로 작성한 요구사항 정의서의 내용이다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "동네 세탁소 예약 서비스 기획 프로젝트에서 세탁소 5곳을 인터뷰했다.",
          "task": "기획 담당으로 요구사항 정의서를 작성하고 개발 담당 팀원과 범위를 조정했다.",
          "action": "실제 요구사항 정의서에 요청의 목적, 포함·제외 범위, 우선순위와 예외를 어떤 내용으로 적었는지 설명한다.",
          "result": "설명한 문서 내용에서 개발·디자인 담당자가 구현할 범위를 구분할 수 있었는지 드러난다."
        },
        "expectedEvidence": [
          "실제 요구사항 정의서에 작성한 구체적인 내용",
          "문서에 드러난 요청의 목적과 구현 범위의 연결",
          "포함·제외 범위, 우선순위, 예외를 구분한 문서 표현"
        ]
      },
      "question": "동네 세탁소 예약 서비스 기획에서 세탁소 5곳 인터뷰로 요구사항 정의서를 쓰셨을 때, 요구사항 정의서에 담은 내용은 무엇이었나요?",
      "answerTip": "기억나는 내용을 구체적으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "실제 문서에 적은 요구사항을 구체적으로 제시하며 요청의 목적과 구현 범위가 연결되어 있다.",
            "문서 내용에서 포함·제외 범위, 우선순위와 예외를 구분할 수 있어 개발·디자인 담당자가 구현 대상을 이해할 수 있다."
          ]
        },
        "acceptable": {
          "criteria": [
            "요구사항 정의서에 적은 기능이나 요청 내용을 제시하지만 목적과 구현 범위의 연결이 일반적이다.",
            "문서에 범위는 드러나지만 포함·제외 항목, 우선순위 또는 예외의 구분이 일부 불명확하다."
          ]
        },
        "poor": {
          "criteria": [
            "실제로 작성한 문서 내용 없이 요구사항 정의서의 일반적인 구성이나 필요성만 말한다.",
            "인터뷰 활동이나 협업 경험만 설명해 문서에서 구현 범위를 어떻게 구체화했는지 확인할 수 없다."
          ]
        }
      }
    },
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "화면 흐름과 예외 상황을 개발·디자인 담당자가 구현할 수 있는 화면설계서로 표현하는 능력을 검증한다. 판단 초점은 예외 상황 하나를 화면설계서에 실제로 기술한 내용이다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "동네 세탁소 예약 서비스 기획 프로젝트에서 예약·취소·알림 흐름과 예외 상황을 설계했다.",
          "task": "기획 담당으로 Figma를 사용해 화면설계서 28장을 작성했다.",
          "action": "화면설계서에 담은 예외 상황 하나를 골라 해당 화면의 상태, 화면 간 이동 또는 안내 문구를 실제로 어떻게 적었는지 설명한다.",
          "result": "설명한 설계 내용에서 예외가 발생했을 때 화면이 어떻게 반응하는지 구현 담당자가 이해할 수 있는 수준이 드러난다."
        },
        "expectedEvidence": [
          "예외 상황 하나를 화면설계서에 실제로 기술한 내용",
          "해당 예외가 발생하는 조건과 화면 반응의 연결",
          "화면 상태나 이동, 안내 문구를 해석할 수 있는 구체적인 표현"
        ]
      },
      "question": "동네 세탁소 예약 서비스 기획에서 Figma로 화면설계서 28장을 작성하셨을 때, 예외 상황 하나를 화면설계서에 어떤 내용으로 담으셨나요?",
      "answerTip": "한 가지 사례에 집중해 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "실제로 설계한 예외 상황 하나를 제시하고 그 상황에서 화면에 나타나는 동작이나 상태를 구체적으로 설명한다.",
            "화면설계서에 적은 내용만으로 예외 발생 조건과 화면 반응을 연결할 수 있으며 안내 문구나 이동 대상에도 구현에 필요한 설명이 있다."
          ]
        },
        "acceptable": {
          "criteria": [
            "실제로 설계한 예외 상황과 화면 반응을 제시하지만 화면설계서에 적은 표현은 개략적이다.",
            "예외 발생 조건과 화면 반응의 연결은 이해되지만 상태나 안내 문구 등의 일부 내용은 추가 해석이 필요하다."
          ]
        },
        "poor": {
          "criteria": [
            "실제 화면설계서에 담은 예외 상황을 제시하지 못하고 예외 처리의 중요성이나 도구 사용법만 설명한다.",
            "예외 상황의 이름만 나열하거나 정상 흐름만 설명해 예외 발생 시 화면이 어떻게 반응하는지 확인할 수 없다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P03",
  "interviews": [
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "처방 용량이 의심스러울 때 확인 없이 투약하지 않는 행동을 검증한다. 판단 초점은 의심스러운 처방에 따라 투약하기 전에 멈추고 담당자에게 확인하는 조치다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "푸른결종합병원 근무 2년 차에 수술 후 환자의 진통제 처방 용량이 평소 용량의 두 배로 들어왔다.",
          "task": "수술 전후 환자의 투약과 처치를 맡았다.",
          "action": "투약을 멈추고 담당의에게 처방 용량을 확인한 실제 조치를 설명한다.",
          "result": "담당의에게 확인해 처방 입력 오류임을 확인한 결과를 설명한다."
        },
        "expectedEvidence": [
          "의심스러운 처방을 받은 뒤 투약 전에 실제로 취한 조치",
          "확인이 끝나기 전 투약을 보류했는지 드러나는 설명",
          "담당의에게 확인한 처방 내용"
        ]
      },
      "question": "푸른결종합병원에서 진통제 처방 용량이 평소의 두 배로 들어왔을 때, 투약 전에 실제로 취하신 조치는 무엇이었나요?",
      "answerTip": "본인이 한 일을 중심으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "처방 용량에 의문이 생겨 투약을 멈춘 조치를 구체적으로 답한다.",
            "담당의에게 해당 처방 용량을 확인했다고 답해 확인 없이 투약하지 않았음이 드러난다."
          ]
        },
        "acceptable": {
          "criteria": [
            "투약 보류나 처방 확인 조치를 답하지만 실제 행동의 설명이 포괄적이다.",
            "확인 대상이나 투약 보류 시점이 일부 불분명하지만 의심스러운 처방을 그대로 수행하지 않았다는 취지는 드러난다."
          ]
        },
        "poor": {
          "criteria": [
            "투약 전에 취한 조치를 답하지 못하고 투약 안전의 중요성만 말한다.",
            "의심스러운 용량을 확인 없이 투약했다고 답하거나 담당자 확인이 필요하지 않다고 말한다."
          ]
        }
      }
    },
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "관찰한 환자 상태의 변화를 간호 기록에 구체적으로 남길 수 있는지 검증한다. 판단 초점은 활력징후와 통증의 변화가 드러나도록 실제 관찰 내용을 기록하는 행동이다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "푸른결종합병원 정형외과 병동에서 수술 전후 환자를 간호했다.",
          "task": "환자의 활력징후와 통증 관찰 기록을 맡았다.",
          "action": "관찰한 활력징후와 통증을 간호 기록에 실제로 어떤 내용으로 남겼는지 설명한다.",
          "result": "설명한 기록 내용에서 환자 상태와 시간에 따른 변화를 파악할 수 있음을 보여준다."
        },
        "expectedEvidence": [
          "환자 상태의 변화를 간호 기록에 실제로 남긴 내용",
          "기록 내용을 뒷받침하는 관찰 시점과 측정값 또는 환자의 통증 표현",
          "이전 관찰 내용과 비교해 상태 변화가 드러나는 기록 표현"
